/// Scenario directory: `$GROW_CONFORMANCE_DIR` when set, else `<dir>/../conformance/scenarios`
/// relative to the given crate directory (pass `env!("CARGO_MANIFEST_DIR")`).
pub fn scenarios_dir(manifest_dir: &str) -> std::path::PathBuf {
    match std::env::var_os("GROW_CONFORMANCE_DIR") {
        Some(dir) if !dir.is_empty() => dir.into(),
        _ => std::path::Path::new(manifest_dir).join("../conformance/scenarios"),
    }
}
